sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    //gs.info("OHSM Testing: H&V Trigger Notification BR run :" + current.number + ":");

    function getEmailFromDetails(record, details_text, label_text_en, label_text_fr, notification) {
        var section_delim = "<p class=\"descriptionFormatted\">";
        var start_email_regex = /.*<br \/><strong>/g;
        var end_email_regex = /<\/strong><\/p>/g;
        var email = '';

        if (details_text.includes(label_text_en) || details_text.includes(label_text_fr)) {

            var details_arr = details_text.split(section_delim);

            var i = 0;

            while (email === '' && i < details_arr.length) {
                if (details_arr[i].includes(label_text_en) || details_arr[i].includes(label_text_fr)) {

                    email = details_arr[i].replace(start_email_regex, '').replace(end_email_regex, '');
                    email = email.replace("&#64;", "@");

                    gs.eventQueue(notification, record, email);
                }
                i += 1;
            }
        }
    }

    // Extract the submitter email from submitter_contact_details
    var en_submitter_label = "Submitter email address";
    var fr_submitter_label = "Adresse courriel du demandeur";

    getEmailFromDetails(current, current.submitter_contact_details.toString(), en_submitter_label, fr_submitter_label,
        'x_hccc_hoc_ohs.hv_submitter_notification');


    // Extract the complainant email from complainant_contact_details
    var en_complainant_label = "Principal party&#39;s email address";
    var fr_complainant_label = "Adresse courriel de la partie principale";

    getEmailFromDetails(current, current.complainant_contact_details.toString(), en_complainant_label, fr_complainant_label,
        'x_hccc_hoc_ohs.hv_complainant_notification');
	getEmailFromDetails(current, current.complainant_contact_details.toString(), en_complainant_label, fr_complainant_label,
        'x_hccc_hoc_ohs.hv_submitter_notification');



})(current, previous);
